301	import com.fream.back.domain.notification.service.command.NotificationCommandService;
302	import com.fream.back.domain.shipment.entity.OrderShipment;
303	import com.fream.back.domain.shipment.entity.ShipmentStatus;
304	import com.fream.back.domain.shipment.exception.ShipmentErrorCode;
305	import com.fream.back.domain.shipment.exception.ShipmentException;
306	import com.fream.back.domain.shipment.repository.OrderShipmentRepository;
307	import com.fream.back.domain.shipment.service.command.OrderShipmentCommandService;
308	import com.fream.back.global.utils.CjTrackingPlaywright;
309	import com.fream.back.global.utils.PlaywrightBrowserManager;
310	import jakarta.persistence.EntityManagerFactory;
311	import lombok.RequiredArgsConstructor;
312	import lombok.extern.slf4j.Slf4j;
313	import org.jsoup.Jsoup;
314	import org.jsoup.nodes.Document;
315	import org.jsoup.select.Elements;
316	import org.springframework.batch.core.Job;
317	import org.springframework.batch.core.SkipListener;
318	import org.springframework.batch.core.Step;
319	import org.springframework.batch.core.configuration.annotation.StepScope;
320	import org.springframework.batch.core.job.builder.JobBuilder;
321	import org.springframework.batch.core.repository.JobRepository;
322	import org.springframework.batch.core.step.builder.StepBuilder;
323	import org.springframework.batch.item.ItemProcessor;
324	import org.springframework.batch.item.database.JpaItemWriter;
325	import org.springframework.batch.item.database.JpaPagingItemReader;
326	import org.springframework.batch.item.database.builder.JpaPagingItemReaderBuilder;
327	import org.springframework.context.annotation.Bean;
328	import org.springframework.context.annotation.Configuration;
