260	/**
261	 * 배송 상태 자동 업데이트를 위한 배치 작업 구성
262	 */
263	@Slf4j
264	@Configuration
265	@RequiredArgsConstructor
266	public class UpdateShipmentStatusesJobConfig {
267	
268	    private final JobRepository jobRepository;
269	    private final PlatformTransactionManager transactionManager;
270	    private final EntityManagerFactory entityManagerFactory;
271	
272	    private final OrderShipmentRepository orderShipmentRepository;
273	    private final NotificationCommandService notificationService;
274	    private final OrderShipmentCommandService orderService;
275	    private final CjTrackingPlaywright cjTrackingPlaywright;
276	
277	    private static final int CHUNK_SIZE = 50;
278	    private static final int SKIP_LIMIT = 50;
279	
280	    @Bean
281	    public Job updateShipmentStatusesJob() {
282	        log.info("배송 상태 업데이트 작업 구성");
283	        return new JobBuilder("updateShipmentStatusesJob", jobRepository)
284	                .start(updateShipmentStatusesStep())
285	                .build();
286	    }
287	
288	    @Bean
289	    public Step updateShipmentStatusesStep() {
290	        log.info("배송 상태 업데이트 스텝 구성: 청크 크기={}, 스킵 제한={}", CHUNK_SIZE, SKIP_LIMIT);
291	
292	        return new StepBuilder("updateShipmentStatusesStep", jobRepository)
293	                .<OrderShipment, OrderShipment>chunk(CHUNK_SIZE, transactionManager)
294	                .reader(shipmentItemReader())
295	                .processor(new ShipmentItemProcessor(
296	                        playwrightBrowserManager(), // Bean or new
297	                        notificationService,
298	                        orderService
299	                ))
300	                .writer(shipmentJpaItemWriter())
301	                .faultTolerant()
302	                .skip(Exception.class)
303	                .skipLimit(SKIP_LIMIT)
304	                .listener(shipmentSkipListener())
305	                // ★ Step Execution Listener로 Browser 관리 리스너 추가
306	                .listener(new BrowserManageStepListener(playwrightBrowserManager()))
307	                .build();
308	    }
309	
310	    /**
311	     * 1) Reader: 상태가 IN_TRANSIT 또는 OUT_FOR_DELIVERY 인 OrderShipment 목록을 페이지 단위로 읽음
312	     */
313	    @Bean
314	    @StepScope
315	    public JpaPagingItemReader<OrderShipment> shipmentItemReader() {
316	        log.debug("배송 상태 업데이트 ItemReader 구성");
317	        return new JpaPagingItemReaderBuilder<OrderShipment>()
318	                .name("shipmentItemReader")
319	                .entityManagerFactory(entityManagerFactory)
320	                .pageSize(CHUNK_SIZE)
321	                .queryString("SELECT s FROM OrderShipment s WHERE s.status IN ('IN_TRANSIT','OUT_FOR_DELIVERY') AND s.trackingNumber IS NOT NULL")
322	                .build();
323	    }
324	
325	    /**
326	     * 2) Processor: 각 OrderShipment에 대해 CJ대한통운 페이지를 조회하여 상태 갱신
327	     *    - parseCjLogisticsStatus(...) 를 통해 배송 상태 파싱
328	     *    - DELIVERY 완료 시 알림, Order 상태 완료 등도 여기서 처리 가능
329	     */
330	    @Bean
331	    @StepScope
332	    public ItemProcessor<OrderShipment, OrderShipment> shipmentItemProcessor() {
333	        log.debug("배송 상태 업데이트 ItemProcessor 구성");
334	
335	        // 만약 Processor를 여러 단계로 나누고 싶다면 CompositeItemProcessorBuilder 사용도 가능
336	        return orderShipment -> {
337	            String trackingNumber = orderShipment.getTrackingNumber();
338	            Long shipmentId = orderShipment.getId();
339	
340	            if (trackingNumber == null || trackingNumber.isBlank()) {
341	                log.warn("유효하지 않은 운송장 번호: shipmentId={}", shipmentId);
342	                throw new ShipmentException(ShipmentErrorCode.TRACKING_NUMBER_INVALID);
343	            }
344	
345	            log.info("배송 상태 조회 시작: shipmentId={}, trackingNumber={}, currentStatus={}",
346	                    shipmentId, trackingNumber, orderShipment.getStatus());
347	
348	            try {
349	                // 2-1) 현재 상태 가져오기
350	                String currentStatus = cjTrackingPlaywright.getCurrentTrackingStatus(trackingNumber);
351	                log.debug("배송 상태 조회 결과: shipmentId={}, currentStatus={}", shipmentId, currentStatus);
352	
353	                // 2-2) 매핑
354	                ShipmentStatus newStatus = mapToShipmentStatus(currentStatus);
355	                log.debug("배송 상태 매핑 결과: currentStatus={}, mappedStatus={}", currentStatus, newStatus);
356	
357	                // 현재 상태와 동일한 경우 중복 처리 방지
358	                if (orderShipment.getStatus() == newStatus) {
359	                    log.debug("상태 변경 없음 (중복 처리 방지): shipmentId={}, status={}",
360	                            shipmentId, newStatus);
361	                    return orderShipment;
362	                }
363	
364	                // 2-3) 상태에 따른 처리
365	                if (newStatus == ShipmentStatus.DELIVERED) {
366	                    log.info("배송 완료 처리: shipmentId={}, orderId={}",
367	                            shipmentId, orderShipment.getOrder().getId());
368	
369	                    orderShipment.updateStatus(ShipmentStatus.DELIVERED);
370	                    // Order 상태도 COMPLETED 로 변경
371	                    orderService.completeOrder(orderShipment.getOrder().getId());
372	                    // 알림 발송
373	                    notificationService.notifyShipmentCompleted(orderShipment.getOrder());
374	                }
375	                else if (newStatus == ShipmentStatus.OUT_FOR_DELIVERY) {
376	                    log.info("배송 출발 처리: shipmentId={}", shipmentId);
377	                    orderShipment.updateStatus(ShipmentStatus.OUT_FOR_DELIVERY);
378	                    // 필요시 알림, 로직 추가
379	                }
380	                else {
381	                    log.info("배송 중 상태 업데이트: shipmentId={}", shipmentId);
382	                    orderShipment.updateStatus(ShipmentStatus.IN_TRANSIT);
383	                }
384	
385	                log.info("배송 상태 처리 완료: shipmentId={}, newStatus={}", shipmentId, orderShipment.getStatus());
386	                return orderShipment; // Writer로 넘김
387	
388	            } catch (Exception e) {
389	                log.error("배송 상태 처리 중 오류 발생: shipmentId={}, trackingNumber={}, error={}",
390	                        shipmentId, trackingNumber, e.getMessage(), e);
391	
392	                // ShipmentException 타입이 아닌 경우 래핑
393	                if (!(e instanceof ShipmentException)) {
394	                    throw new ShipmentException(
395	                            ShipmentErrorCode.EXTERNAL_TRACKING_SERVICE_ERROR,
396	                            "배송 상태 조회 중 오류 발생: " + e.getMessage(),
397	                            e
398	                    );
399	                }
400	                throw e;
401	            }
402	        };
403	    }
404	
405	    /**
406	     * CJ대한통운 배송 상태 조회를 위한 메서드
407	     *
408	     * @param trackingNumber 운송장 번호
409	     * @return 배송 상태 텍스트
410	     * @throws Exception 조회 실패 시 발생
411	     */
412	    private String parseCjLogisticsStatus(String trackingNumber) throws Exception {
413	        log.debug("운송장 조회 시작 (Jsoup): trackingNumber={}", trackingNumber);
414	
415	        try {
416	            // 예시: 로직 단순화
417	            String url = "https://trace.cjlogistics.com/next/tracking.html?wblNo=" + trackingNumber;
418	            Document doc = Jsoup.connect(url).get();
419	            // tbody#statusDetail 의 마지막 tr => 5번째 td
420	            Elements rows = doc.select("tbody#statusDetail tr");
421	            if (rows.isEmpty()) {
422	                log.warn("배송 정보가 없음: trackingNumber={}", trackingNumber);
423	                throw new ShipmentException(
424	                        ShipmentErrorCode.TRACKING_HTML_PARSE_ERROR,
