452	     * @return 매핑된 ShipmentStatus
453	     */
454	    private ShipmentStatus mapToShipmentStatus(String statusText) {
455	        return switch (statusText) {
456	            case "배송완료" -> ShipmentStatus.DELIVERED;
457	            case "배송출발" -> ShipmentStatus.OUT_FOR_DELIVERY;
458	            default -> ShipmentStatus.IN_TRANSIT;
459	        };
460	    }
